structs.clog:
struct clog
{
    enum clog_level level;
    int fd;
    char fmt[256];
    char date_fmt[256];
    char time_fmt[256];
    int opened;
}

functions.clog_init_path:
int clog_init_path(int id, const char *const path)
{
    int fd = open(path, 0100 | 01 | 02000, 0666);
    if (fd == -1)
    {
        _clog_err("Unable to open %s: %s\n", path, strerror((*__errno_location())));
        return 1;
    }
    if (clog_init_fd(id, fd))
    {
        close(fd);
        return 1;
    }
    _clog_loggers[id]->opened = 1;
    return 0;
}

functions.clog_init_fd:
int clog_init_fd(int id, int fd)
{
    struct clog *logger;
    if (_clog_loggers[id] != ((void *)0))
    {
        _clog_err("Logger %d already initialized.\n", id);
        return 1;
    }
    logger = (struct clog *)malloc(sizeof(struct clog));
    if (logger == ((void *)0))
    {
        _clog_err("Failed to allocate logger: %s\n", strerror((*__errno_location())));
        return 1;
    }
    logger->level = CLOG_DEBUG;
    logger->fd = fd;
    logger->opened = 0;
    strcpy(logger->fmt, "%d %t %f(%n): %l: %m\n");
    strcpy(logger->date_fmt, "%Y-%m-%d");
    strcpy(logger->time_fmt, "%H:%M:%S");
    _clog_loggers[id] = logger;
    return 0;
}

functions.clog_free:
void clog_free(int id)
{
    if (_clog_loggers[id])
    {
        if (_clog_loggers[id]->opened)
        {
            close(_clog_loggers[id]->fd);
        }
        free(_clog_loggers[id]);
        _clog_loggers[id] = ((void *)0);
    }
}

functions.clog_set_level:
int clog_set_level(int id, enum clog_level level)
{
    if (_clog_loggers[id] == ((void *)0))
    {
        return 1;
    }
    if ((unsigned)level > CLOG_ERROR)
    {
        return 1;
    }
    _clog_loggers[id]->level = level;
    return 0;
}

functions.clog_set_time_fmt:
int clog_set_time_fmt(int id, const char *fmt)
{
    struct clog *logger = _clog_loggers[id];
    if (logger == ((void *)0))
    {
        _clog_err("clog_set_time_fmt: No such logger: %d\n", id);
        return 1;
    }
    if (strlen(fmt) >= 256)
    {
        _clog_err("clog_set_time_fmt: Format specifier too long.\n");
        return 1;
    }
    strcpy(logger->time_fmt, fmt);
    return 0;
}

