functions._clog_append_str:
size_t _clog_append_str(char **dst, char *orig_buf, const char *src, size_t cur_size)
{
    size_t new_size = cur_size;
    while (strlen(*dst) + strlen(src) >= new_size)
    {
        new_size *= 2;
    }
    if (new_size != cur_size)
    {
        if (*dst == orig_buf)
        {
            *dst = (char *)malloc(new_size);
            strcpy(*dst, orig_buf);
        }
        else
        {
            *dst = (char *)realloc(*dst, new_size);
        }
    }
    strcat(*dst, src);
    return new_size;
}

functions._clog_append_int:
size_t _clog_append_int(char **dst, char *orig_buf, long int d, size_t cur_size)
{
    char buf[40];
    if (snprintf(buf, 40, "%ld", d) >= 40)
    {
        return cur_size;
    }
    return _clog_append_str(dst, orig_buf, buf, cur_size);
}

functions._clog_append_time:
size_t _clog_append_time(char **dst, char *orig_buf, struct tm *lt, const char *fmt, size_t cur_size)
{
    char buf[256];
    size_t result = strftime(buf, 256, fmt, lt);
    if (result > 0)
    {
        return _clog_append_str(dst, orig_buf, buf, cur_size);
    }
    return cur_size;
}

functions._clog_basename:
const char *_clog_basename(const char *path)
{
    const char *slash = strrchr(path, '/');
    if (slash)
    {
        path = slash + 1;
    }
    return path;
}

functions._clog_format:
char *_clog_format(const struct clog *logger, char buf[], size_t buf_size, const char *sfile, int sline,
                   const char *level, const char *message)
{
    size_t cur_size = buf_size;
    char *result = buf;
    enum
    {
        NORMAL,
        SUBST
    } state = NORMAL;
    size_t fmtlen = strlen(logger->fmt);
    size_t i;
    time_t t = time(((void *)0));
    struct tm *lt = localtime(&t);
    sfile = _clog_basename(sfile);
    result[0] = 0;
    for (i = 0; i < fmtlen; ++i)
    {
        if (state == NORMAL)
        {
            if (logger->fmt[i] == '%')
            {
                state = SUBST;
            }
            else
            {
                char str[2] = {0};
                str[0] = logger->fmt[i];
                cur_size = _clog_append_str(&result, buf, str, cur_size);
            }
        }
        else
        {
            switch (logger->fmt[i])
            {
            case '%':
                cur_size = _clog_append_str(&result, buf, "%", cur_size);
                break;
            case 't':
                cur_size = _clog_append_time(&result, buf, lt, logger->time_fmt, cur_size);
                break;
            case 'd':
                cur_size = _clog_append_time(&result, buf, lt, logger->date_fmt, cur_size);
                break;
            case 'l':
                cur_size = _clog_append_str(&result, buf, level, cur_size);
                break;
            case 'n':
                cur_size = _clog_append_int(&result, buf, sline, cur_size);
                break;
            case 'f':
                cur_size = _clog_append_str(&result, buf, sfile, cur_size);
                break;
            case 'm':
                cur_size = _clog_append_str(&result, buf, message, cur_size);
                break;
            }
            state = NORMAL;
        }
    }
    return result;
}

functions._clog_log:
void _clog_log(const char *sfile, int sline, enum clog_level level, int id, const char *fmt, va_list ap)
{
    char buf[4096];
    size_t buf_size = 4096;
    char *dynbuf = buf;
    char *message;
    va_list ap_copy;
    int result;
    struct clog *logger = _clog_loggers[id];
    if (!logger)
    {
        _clog_err("No such logger: %d\n", id);
        return;
    }
    if (level < logger->level)
    {
        return;
    }
    __builtin_va_copy(ap_copy, ap);
    result = vsnprintf(dynbuf, buf_size, fmt, ap);
    if ((size_t)result >= buf_size)
    {
        buf_size = result + 1;
        dynbuf = (char *)malloc(buf_size);
        result = vsnprintf(dynbuf, buf_size, fmt, ap_copy);
        if ((size_t)result >= buf_size)
        {
            _clog_err("Formatting failed (1).\n");
            __builtin_va_end(ap_copy);
            free(dynbuf);
            return;
        }
    }
    __builtin_va_end(ap_copy);
    {
        char message_buf[4096];
        message = _clog_format(logger, message_buf, 4096, sfile, sline, CLOG_LEVEL_NAMES[level], dynbuf);
        if (!message)
        {
            _clog_err("Formatting failed (2).\n");
            if (dynbuf != buf)
            {
                free(dynbuf);
            }
            return;
        }
        result = write(logger->fd, message, strlen(message));
        if (result == -1)
        {
            _clog_err("Unable to write to log file: %s\n", strerror((*__errno_location())));
        }
        if (message != message_buf)
        {
            free(message);
        }
        if (dynbuf != buf)
        {
            free(dynbuf);
        }
    }
}

functions.clog_debug:
void clog_debug(const char *sfile, int sline, int id, const char *fmt, ...)
{
    va_list ap;
    __builtin_va_start(ap, fmt);
    _clog_log(sfile, sline, CLOG_DEBUG, id, fmt, ap);
    __builtin_va_end(ap);
}

